/* Static SVG/HTML generated by C. No JavaScript, CDN or interpolation of gaps. */
#include "neck_replay_internal.h"
#include <math.h>
#include <string.h>
typedef struct { unsigned kind,axis,pair; const char *name,*color; int step; } Series;
enum { RAW=0,FILTERED=1,CORRECTED=2,IDEAL=3,INSTANT=4,ALARM=5,TIMER=6,QUALITY=7,RELATIVE=8,BODY=9 };
static int value(const Series *s,const NRPoint *p,const NRTruths *truth,double *v)
{
    const NeckReplayTruth *t; double proxy[2]; uint8_t mask;
    unsigned a=s->axis;
    switch(s->kind) {
    case RAW: *v=p->raw[a]; return (p->raw_mask&(a?NECK_VALID_LATERAL_RAW:NECK_VALID_PITCH_RAW))!=0;
    case FILTERED: *v=p->filtered[a]; return (p->filtered_mask&(a?NECK_VALID_LATERAL_RAW:NECK_VALID_PITCH_RAW))!=0;
    case CORRECTED: *v=p->corrected[a]; return (p->filtered_mask&(a?NECK_VALID_RIGHT_LATERAL:NECK_VALID_FLEXION))!=0;
    case IDEAL:
        t=nr_truth_at(truth,p->time_us,p->source); if(t==NULL) return 0;
        neck_replay_ideal_proxy(t->euler_deg[1][0],t->euler_deg[1][1],proxy,&mask);
        *v=proxy[a]; return (mask&(1u<<a))!=0;
    case BODY: t=nr_truth_at(truth,p->time_us,p->source); if(t==NULL) return 0; *v=t->euler_deg[1][a]; return 1;
    case INSTANT: *v=p->instant[a]; return 1; /* UNKNOWN is a category, not an angle */
    case ALARM: *v=p->alarm[a]; return 1;
    case TIMER: *v=(double)p->timers[a]*1e-6; return 1;
    case QUALITY: *v=a==0?p->accel_mask:(a==1?p->quat_mask:(p->valid[0]?7:0)); return 1;
    case RELATIVE: *v=p->relative[s->pair][a]; return (p->relative_masks[s->pair]&NECK_REL_CORRECTED_EULER)!=0;
    default: return 0;
    }
}
static void range_time(const NRPoints *p,uint64_t *begin,uint64_t *end)
{
    size_t i; *begin=*end=p->count?p->items[0].time_us:0;
    for(i=1;i<p->count;++i) { if(p->items[i].time_us<*begin) *begin=p->items[i].time_us; if(p->items[i].time_us>*end) *end=p->items[i].time_us; }
}
static double xpos(uint64_t time,uint64_t begin,uint64_t end)
{ return 72+1048*(end==begin?0:((double)(time-begin)/(double)(end-begin))); }
static double ypos(double v,double low,double high)
{ return 236-160*(v-low)/(high-low); }
static int graph(const char *dir,const char *name,const char *title,const char *unit,
    const Series *series,unsigned n,const double *thresholds,unsigned n_thresholds,
    const NRPoints *points,const NRTruths *truth,const NeckReplayConfig *cfg,
    int categorical,NeckReplayError *e)
{
    FILE *f; unsigned j,k; size_t i; uint64_t begin,end; double low=0,high=0,v; int any=0;
    range_time(points,&begin,&end);
    for(j=0;j<n;++j) for(i=0;i<points->count;++i) if(value(&series[j],&points->items[i],truth,&v) && isfinite(v)) {
        if(!any) { low=high=v; any=1; } else { if(v<low) low=v; if(v>high) high=v; }
    }
    for(j=0;j<n_thresholds;++j) { if(thresholds[j]<low) low=thresholds[j]; if(thresholds[j]>high) high=thresholds[j]; }
    if(categorical==1) { low=-.2; high=4.2; }
    else if(categorical==2) { low=-.4; high=7.4; }
    else { double pad=(high-low)*.1; if(pad<1) pad=1; low-=pad; high+=pad; }
    f=nr_new_file(dir,name,e); if(f==NULL) return NR_IO;
    fprintf(f,"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 1200 340\" role=\"img\" aria-label=\"%s\"><title>%s</title>\n",title,title);
    fputs("<rect width=\"1200\" height=\"340\" fill=\"#fff\"/><g font-family=\"Arial, sans-serif\" font-size=\"13\" fill=\"#334155\">\n",f);
    fprintf(f,"<text x=\"24\" y=\"26\" font-size=\"18\">%s</text><text x=\"24\" y=\"47\">OFFLINE REPLAY | NOT hardware validation | %s</text>\n",title,unit);
    for(k=0;k<=4;++k) {
        double val=categorical==1?(double)k:low+(high-low)*(double)k/4,yy=ypos(val,low,high);
        if(fabs(val)<1e-10) val=0; /* label only, not data rounding */
        fprintf(f,"<path d=\"M72 %.3fH1120\" stroke=\"#e2e8f0\"/><text x=\"64\" y=\"%.3f\" text-anchor=\"end\">%.3g</text>\n",yy,yy+4,val);
    }
    for(k=0;k<=5;++k) {
        double xx=72+1048*(double)k/5,sec=(double)(end-begin)*1e-6*(double)k/5;
        fprintf(f,"<path d=\"M%.3f 76V236\" stroke=\"#f1f5f9\"/><text x=\"%.3f\" y=\"257\" text-anchor=\"middle\">%.4g</text>\n",xx,xx,sec);
    }
    for(j=0;j<n_thresholds;++j) {
        double yy=ypos(thresholds[j],low,high);
        fprintf(f,"<path d=\"M72 %.3fH1120\" stroke=\"#94a3b8\" stroke-dasharray=\"6 5\"/><text x=\"1128\" y=\"%.3f\">%.3g</text>\n",yy,yy+4,thresholds[j]);
    }
    for(j=0;j<n;++j) {
        int connected=0; uint64_t prev_time=0; uint32_t prev_epoch=0; double prev_y=0;
        fprintf(f,"<path data-series=\"%s\" fill=\"none\" stroke=\"%s\" stroke-width=\"1.5\" d=\"",series[j].name,series[j].color);
        for(i=0;i<points->count;++i) {
            const NRPoint *p=&points->items[i]; double xx,yy;
            if(!value(&series[j],p,truth,&v) || !isfinite(v)) { connected=0; continue; }
            if(connected && (p->time_us<=prev_time || p->time_us-prev_time>cfg->parameters.pipeline.max_gap_us ||
                ((series[j].kind==CORRECTED || series[j].kind==RELATIVE || series[j].kind==FILTERED) && p->epoch!=prev_epoch))) connected=0;
            xx=xpos(p->time_us,begin,end); yy=ypos(v,low,high);
            if(!connected) fprintf(f,"M%.3f %.3f",xx,yy);
            else if(series[j].step) fprintf(f,"L%.3f %.3fL%.3f %.3f",xx,prev_y,xx,yy);
            else fprintf(f,"L%.3f %.3f",xx,yy);
            connected=1; prev_time=p->time_us; prev_epoch=p->epoch; prev_y=yy;
        }
        fputs("\"/>\n",f);
        fprintf(f,"<path d=\"M%u 282h18\" stroke=\"%s\" stroke-width=\"3\"/><text x=\"%u\" y=\"286\">%s</text>\n",72+j*200,series[j].color,96+j*200,series[j].name);
    }
    fputs("<text x=\"72\" y=\"313\">Time (s) relative to earliest decision; invalid values / gaps break paths. No resampling.</text>\n",f);
    if(!any) fputs("<text x=\"470\" y=\"150\" font-size=\"20\">No valid samples</text>\n",f);
    fputs("</g></svg>\n",f); return nr_close(f,e);
}
int nr_plots(const char *dir,const NRPoints *p,const NRTruths *t,const NeckReplayConfig *c,NeckReplayError *e)
{
    static const char *const relnames[4]={"Overall C7 reference / C0 target","Upper C4 reference / C0 target","Lower C7 reference / C4 target","Base world reference / C7 target"};
    const char *colors[3]={"#0f766e","#c2410c","#6d28d9"}; unsigned i,j; int status;
    Series raw[]={{IDEAL,0,0,"construction proxy P","#64748b",0},{RAW,0,0,"raw proxy P","#f97316",0},{FILTERED,0,0,"LP proxy P","#0f766e",0},{RAW,1,0,"raw proxy L","#7c3aed",0},{FILTERED,1,0,"LP proxy L","#2563eb",0}};
    Series corrected[]={{CORRECTED,0,0,"corrected flexion","#0f766e",0},{CORRECTED,1,0,"corrected right lateral","#6d28d9",0}};
    Series levels[]={{INSTANT,0,0,"flex instant","#14b8a6",1},{ALARM,0,0,"flex alarm","#0f766e",1},{INSTANT,1,0,"lateral instant","#fb923c",1},{ALARM,1,0,"lateral alarm","#c2410c",1}};
    Series timers[]={{TIMER,0,0,"flex warning","#0f766e",1},{TIMER,1,0,"flex danger","#b91c1c",1},{TIMER,2,0,"extension","#6d28d9",1},{TIMER,3,0,"lateral warning","#f97316",1},{TIMER,4,0,"lateral danger","#2563eb",1}};
    Series quality[]={{QUALITY,0,0,"accel bitmask","#0f766e",1},{QUALITY,1,0,"quat bitmask","#c2410c",1},{QUALITY,2,0,"C4 posture valid x7","#6d28d9",1}};
    double ct[]={c->parameters.posture.flexion_warning_deg,c->parameters.posture.flexion_danger_deg,
        c->parameters.posture.lateral_warning_deg,-c->parameters.posture.lateral_warning_deg,
        c->parameters.posture.lateral_danger_deg,-c->parameters.posture.lateral_danger_deg,0};
    double tt=(double)c->parameters.posture.continuous_duration_us*1e-6;
#define GRAPH(name,title,unit,s,ths,nths,cat) do { status=graph(dir,name,title,unit,s,(unsigned)(sizeof(s)/sizeof(s[0])),ths,nths,p,t,c,cat,e); if(status!=NR_OK) return status; } while(0)
    GRAPH("raw_filtered.svg","C4 absolute gravity proxies (NOT general Euler)","degrees; LP before neutral correction",raw,NULL,0,0);
    GRAPH("corrected.svg","C4 corrected angles / S05 thresholds","degrees; engineering thresholds, not clinical criteria",corrected,ct,7,0);
    GRAPH("levels.svg","Instant category and continuous-duration alarm","0 Unknown / 1 Normal / 2 Warning / 3 Danger / 4 Extension (not severity 4)",levels,NULL,0,1);
    GRAPH("timers.svg","Independent continuous-duration clocks","seconds; clocks reset on invalid input",timers,&tt,1,0);
    GRAPH("quality.svg","Software input eligibility (NOT physical confidence)","bits: C0=1 C4=2 C7=4; C4 valid scaled to 7 for visibility",quality,NULL,0,2);
    for(i=0;i<4;++i) {
        Series rel[3]; char name[32];
        for(j=0;j<3;++j) { rel[j].kind=RELATIVE; rel[j].axis=j; rel[j].pair=i; rel[j].color=colors[j]; rel[j].step=0; rel[j].name=j==0?"relative flexion":(j==1?"relative lateral":"relative axial"); }
        (void)snprintf(name,sizeof(name),"relative_%u.svg",i);
        status=graph(dir,name,relnames[i],"corrected Rz*Ry*Rx Euler degrees; relative thresholds UNSET",rel,3,NULL,0,p,t,c,0,e); if(status!=NR_OK) return status;
    }
    if(t->count) {
        Series body[]={{BODY,0,0,"body pitch","#0f766e",0},{BODY,1,0,"body roll","#c2410c",0},{BODY,2,0,"body yaw","#6d28d9",0}};
        GRAPH("construction.svg","Declared C4 construction pose (NOT measured truth)","Rz*Ry*Rx Euler degrees; no physical sensor fusion model",body,NULL,0,0);
    }
#undef GRAPH
    return NR_OK;
}
static void embed(FILE *f,const char *name,const char *caption)
{ fprintf(f,"<figure><img src=\"%s\" alt=\"%s\"><figcaption>%s</figcaption></figure>\n",name,caption,caption); }
static void escaped(FILE *f,const char *s)
{
    for(;*s;++s) { if(*s=='&') fputs("&amp;",f); else if(*s=='<') fputs("&lt;",f); else if(*s=='>') fputs("&gt;",f); else fputc(*s,f); }
}
static int event_table(FILE *out,const char *dir,NeckReplayError *e)
{
    char path[1024],line[NR_LINE_MAX]; FILE *in; uint64_t hash=NR_FNV_OFFSET; unsigned long number=0; unsigned shown=0; int r=0,status=NR_OK;
    if(nr_path(path,dir,"events.csv",e)!=NR_OK) return NR_LIMIT;
    in=fopen(path,"rb"); if(in==NULL) return nr_error(e,NR_IO,"Cannot read generated events for report.");
    if(nr_read_line(in,line,&number,&hash,e)!=1) status=nr_error(e,NR_IO,"Missing generated event header.");
    fputs("<h2>状态机事件</h2><p>掩码：1 触发，2 清除，4 升降级，8 失效，16 方向重置；组合事件为位或。清除与失效可以同时出现。</p><div style=\"overflow:auto\"><table><thead><tr><th>决策时间 / µs</th><th>来源</th><th>轴</th><th>事件掩码</th><th>报警：前 → 后</th><th>有效</th><th>epoch</th></tr></thead><tbody>\n",out);
    while(status==NR_OK && (r=nr_read_line(in,line,&number,&hash,e))==1) {
        char *parts[15],*p; unsigned n=1; parts[0]=line;
        for(p=line;*p;++p) if(*p==',') { *p=0; if(n==15) { status=nr_error(e,NR_FORMAT,"Generated event columns mismatch."); break; } parts[n++]=p+1; }
        if(status!=NR_OK) break;
        if(n!=15) { status=nr_error(e,NR_FORMAT,"Generated event columns mismatch."); break; }
        if(shown>=200) continue;
        fputs("<tr><td>",out); escaped(out,parts[2]); fputs("</td><td>",out); escaped(out,parts[3]); fputs("</td><td>",out);
        escaped(out,parts[4]); fputs("</td><td>",out); escaped(out,parts[5]); fputs("</td><td>",out); escaped(out,parts[6]); fputs(" → ",out);
        escaped(out,parts[7]); fputs("</td><td>",out); escaped(out,parts[9]); fputs("</td><td>",out); escaped(out,parts[14]); fputs("</td></tr>\n",out); ++shown;
    }
    if(!shown) fputs("<tr><td colspan=\"7\">本次回放没有状态机事件。</td></tr>\n",out);
    fputs("</tbody></table></div><p>页面最多列出前 200 条；完整事件、原因码和零位编号见 events.csv。来源 0=模拟，1=硬件标签。</p>\n",out);
    if(status==NR_OK && r<0) status=nr_error(e,NR_IO,"Generated event read failed.");
    if(nr_close(in,e)!=NR_OK) status=NR_IO;
    return status;
}
int nr_index(const char *dir,const NeckReplayStats *s,int has_truth,NeckReplayError *e)
{
    FILE *f=nr_new_file(dir,"index.html",e); int result; char path[1024]; unsigned i;
    if(f==NULL) return NR_IO;
    fputs("<!doctype html><html lang=\"zh-CN\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>S08 · C 离线回放</title>\n"
        "<style>body{margin:0;background:#eef2f6;color:#193047;font:16px/1.65 system-ui,Arial,sans-serif}main{max-width:1200px;margin:32px auto;padding:0 24px}h1{font-size:30px;margin:0}h2{font-size:22px}.banner{background:#193047;color:#fff;padding:24px 28px;border-radius:14px}.banner p{margin:8px 0 0}.warning{border-left:5px solid #c2410c;background:#fff7ed;padding:16px;margin:24px 0}.metrics{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}.metric{flex:1;min-width:130px;background:#fff;padding:14px;border-radius:10px}.metric b{display:block;font-size:25px;color:#0f766e}figure{background:#fff;margin:20px 0;padding:12px;border-radius:12px}img{width:100%;display:block}figcaption{padding:8px 14px;color:#475569;font-size:14px}a{color:#075985}details{margin:24px 0}summary{cursor:pointer;font-weight:600}code{font-size:14px}table{width:100%;border-collapse:collapse;background:#fff;font-size:14px}td,th{padding:10px 14px;text-align:left;border-bottom:1px solid #e2e8f0}footer{color:#64748b;margin:32px 0}</style>\n"
        "<main><header class=\"banner\"><h1>S08 · 颈部姿态纯 C 离线回放</h1><p>保存输入 → 共享 C 处理链 → CSV / 静态 SVG。全离线，无 Python、JavaScript 或外部资源。</p></header>\n"
        "<aside class=\"warning\">模式：<b>OFFLINE_REPLAY</b>。输入来源逐行保存在 CSV 的 source 字段（0 模拟 / 1 硬件标签）。硬件标签只是输入声明，不证明实物测试。质量图只表示软件可用性，不能证明重力假设、佩戴稳定性或医疗准确性。仅当 <a href=\"COMPLETE.txt\">COMPLETE.txt</a> 存在时本次运行才算完成。</aside>\n",f);
    fprintf(f,"<section class=\"metrics\"><div class=\"metric\">输入帧<b>%llu</b></div><div class=\"metric\">输出决策<b>%llu</b></div><div class=\"metric\">拒绝整帧<b>%llu</b></div><div class=\"metric\">报警触发 / 清除<b>%llu / %llu</b></div><div class=\"metric\">超时边沿<b>%llu</b></div></section>\n",
        (unsigned long long)s->input_frames,(unsigned long long)s->outputs,(unsigned long long)s->rejected_frames,(unsigned long long)s->triggers,(unsigned long long)s->clears,(unsigned long long)s->timeout_edges);
    fputs("<nav><a href=\"frames.csv\">决策 CSV</a> · <a href=\"nodes.csv\">三节点 CSV</a> · <a href=\"relative.csv\">四组相对姿态 CSV</a> · <a href=\"events.csv\">事件 CSV</a> · <a href=\"commands.csv\">指令 CSV</a> · <a href=\"config_used.csv\">实际参数</a> · <a href=\"metadata.txt\">可复现记录</a></nav><h2>单点倾角、滤波和持续检测</h2>\n",f);
    embed(f,"raw_filtered.svg","原始与滤波后的绝对加速度倾角代理；不是通用 Euler 分轴角，且尚未减零位。灰线为可选模拟构造代理，绝不进入算法。");
    embed(f,"corrected.svg","显式零位修正后的 C4 前屈 / 右侧屈。虚线来自实际 S05 参数；无效值留空并断线，不补成 0°。");
    embed(f,"levels.svg","瞬时类别与持续时间报警分开显示。0 未知，1 正常，2 警告，3 危险，4 后伸；后伸不是更高危险等级。");
    embed(f,"timers.svg","五个嵌套阈值时钟直接来自 C 状态机；无效期间不累计，恢复后重新计时。");
    embed(f,"quality.svg","节点有效位：C0=1、C4=2、C7=4。0 表示均不可用；7 表示三节点可用，不是质量评分。C4 姿态有效性放大到 7 便于查看。");
    result=event_table(f,dir,e);
    if(result!=NR_OK) {
        (void)nr_close(f,NULL);
        if(nr_path(path,dir,"index.html",NULL)==NR_OK) (void)remove(path);
        return result;
    }
    fputs("<details open><summary>四组相对姿态（阈值未设置，不参与 C4 单点报警）</summary>\n",f);
    for(i=0;i<4;++i) { char name[32]; (void)snprintf(name,sizeof(name),"relative_%u.svg",i); embed(f,name,i==0?"整体：C7 → C0":(i==1?"上段：C4 → C0":(i==2?"下段：C7 → C4":"基座：共同世界 → C7"))); }
    fputs("</details>\n",f);
    if(has_truth) {
        fputs("<details><summary>模拟构造姿态与对照说明</summary><p>真值文件是独立保存的已知模拟构造，不是传感器精度参照。只按决策时间和模拟来源精确连接；不插值，不用于滤波、归零、门控或报警。<a href=\"comparison.csv\">对照 CSV</a>。</p>\n",f);
        embed(f,"construction.svg","已声明的 C4 Euler 构造姿态；组合旋转下请勿与加速度倾角代理直接等同。"); fputs("</details>\n",f);
    }
    fputs("<footer>图中的折线是有效采样点之间的显示连接，不是重采样。无效位、非单调时间、超过配置 max_gap 的间隔均断线；滤波/修正线在相应失效 epoch 切换时断线。实际逐行时间、有效位、原因码和事件以 CSV 为准。离线执行速度不代表 STM32 实时性能。</footer></main></html>\n",f);
    result=nr_close(f,e);
    if(result!=NR_OK && nr_path(path,dir,"index.html",NULL)==NR_OK) (void)remove(path);
    return result;
}
